import { z } from 'zod';

/**
 * Onboarding presets generated by the scanner worker. All fields are
 * AI-generated suggestions the user can later edit. See design/product-flow.md §1.1.
 */
/**
 * Publishing workflow prefs (#73). Exported as a named schema so the API patch
 * bodies can reference `.partial()` — a `.default(...)`-wrapped field cannot be
 * drilled via `.shape`.
 */
export const PublishingPrefsSchema = z.object({ auto_publish: z.boolean().default(false) });

const EngagementPrefsFields = {
  image_style: z.string(),
  include_cta: z.boolean(),
  youtube_videos: z.boolean(),
};

export const EngagementPrefsPatchSchema = z.object(EngagementPrefsFields).partial();

const ContentSeoFields = {
  article_style: z.string(),
  // 0–3 internal links per article (frontend dropdown). Replaces the
  // pre-#73 internal_links boolean.
  internal_links_count: z.number().int().min(0).max(3),
  table_of_contents: z.boolean(),
  // Highest acceptable Flesch–Kincaid grade (#313). Scan-assigned by
  // audience (8 general public / 10 professional / 12 technical), user-
  // editable.
  readability_grade_max: z.number().int().min(6).max(14),
  llm_instructions: z.string(),
};

/**
 * Patch shape for the API's partial content_seo PATCH bodies. Built from the
 * fields *without* their `.default(...)` wrappers: `.partial()` only makes a key
 * optional, so a defaulted key still materializes its default when absent, and
 * the merge would then clobber the stored value (e.g. reset a scan-assigned
 * readability_grade_max back to 8, #313).
 */
export const ContentSeoPatchSchema = z.object(ContentSeoFields).partial();

/** Distinct audience segments a preset may hold (design note). */
export const AUDIENCE_TARGET_MAX = 7;

/** Highest acceptable Flesch–Kincaid grade for English articles when an org has
 * no preset of its own (#313). The scan assigns 8 / 10 / 12 by audience. */
export const READABILITY_GRADE_MAX_DEFAULT = 8;

export const SetupPresetsSchema = z.object({
  business: z.object({
    name: z.string(),
    language: z.string(),
    country: z.string(),
    description: z.string(),
  }),
  audience: z.object({
    // Distinct audience segments (max 7 per design note). The preprocess keeps
    // pre-migration string documents parsing regardless of deploy ordering:
    // '' -> [], non-empty -> [string] — never comma-split, since legacy
    // strings may contain natural-language commas (#99).
    target: z.preprocess(
      (v) => (typeof v === 'string' ? (v === '' ? [] : [v]) : v),
      z.array(z.string()).max(AUDIENCE_TARGET_MAX),
    ),
    competitors: z.array(z.string()),
  }),
  blog: z.object({
    sitemap_url: z.string(),
    main_blog_url: z.string(),
    best_articles: z.array(z.string()),
  }),
  article_preferences: z.object({
    content_seo: z.object({
      ...ContentSeoFields,
      internal_links_count: ContentSeoFields.internal_links_count.default(1),
      table_of_contents: ContentSeoFields.table_of_contents.default(true),
      // The readability default keeps pre-#313 docs and run snapshots parsing.
      readability_grade_max: ContentSeoFields.readability_grade_max.default(
        READABILITY_GRADE_MAX_DEFAULT,
      ),
    }),
    engagement: z.object({
      ...EngagementPrefsFields,
      include_cta: EngagementPrefsFields.include_cta.default(true),
      // YouTube embed toggle (#85; renamed from include_youtube_video in #73).
      youtube_videos: EngagementPrefsFields.youtube_videos.default(true),
    }),
    // Object-level default (with the field spelled out — Zod uses the default
    // value verbatim, it does NOT re-parse it) so scan output that omits
    // publishing (the LLM never produces it) still parses to auto_publish:false.
    publishing: PublishingPrefsSchema.default({ auto_publish: false }),
  }),
});
export type SetupPresets = z.infer<typeof SetupPresetsSchema>;
